 --> <g> <rect x=\"40\" y=\"75\" width=\"170\" height=\"240\" rx=\"10\" fill=\"#0f172a\" stroke=\"#6366f1\" stroke-width=\"1.5\" style=\"filter: drop-shadow(0 4px 12px rgba(0,0,0,0.4));\"/> <rect x=\"40\" y=\"75\" width=\"170\" height=\"32\" rx=\"10 10 0 0\" fill=\"#1e1b4b\"/> <text x=\"54\" y=\"96\" fill=\"#c7d2fe\" font-size=\"12\" font-weight=\"700\" font-family=\"system-ui, -apple-system, sans-serif\">1. fork()</text> <line x1=\"40\" y1=\"107\" x2=\"210\" y2=\"107\" stroke=\"#6366f1\" stroke-width=\"1\" stroke-opacity=\"0.4\"/> <text x=\"54\" y=\"129\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Action: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Clones parent PCB</tspan> </text> <text x=\"54\" y=\"150\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Copy-on-Write: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Shares RAM pages</tspan> </text> <text x=\"54\" y=\"171\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">PID: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">New unique PID assigned</tspan> </text> <text x=\"54\" y=\"192\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Return (Parent): </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Returns Child PID (>0)</tspan> </text> <text x=\"54\" y=\"213\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Return (Child): </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Returns 0</tspan> </text> </g> <g> <path d=\"M 210 195 L 260 195\" stroke=\"#818cf8\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#mIndigo)\"/> <g transform=\"translate(204.0, 185.0)\"> <rect width=\"62.0\" height=\"20\" rx=\"5\" fill=\"#0f172a\" stroke=\"#818cf8\" stroke-width=\"1.2\" style=\"filter: drop-shadow(0 2px 5px rgba(0,0,0,0.5));\"/> <text x=\"31.0\" y=\"14\" fill=\"#f1f5f9\" font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\" font-family=\"system-ui, -apple-system, sans-serif\">execve()</text> </g> </g> <g> <rect x=\"260\" y=\"75\" width=\"180\" height=\"240\" rx=\"10\" fill=\"#0f172a\" stroke=\"#06b6d4\" stroke-width=\"1.5\" style=\"filter: drop-shadow(0 4px 12px rgba(0,0,0,0.4));\"/> <rect x=\"260\" y=\"75\" width=\"180\" height=\"32\" rx=\"10 10 0 0\" fill=\"#155e75\"/> <text x=\"274\" y=\"96\" fill=\"#c7d2fe\" font-size=\"12\" font-weight=\"700\" font-family=\"system-ui, -apple-system, sans-serif\">2. execve()</text> <line x1=\"260\" y1=\"107\" x2=\"440\" y2=\"107\" stroke=\"#06b6d4\" stroke-width=\"1\" stroke-opacity=\"0.4\"/> <text x=\"274\" y=\"129\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Action: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Replaces address space</tspan> </text> <text x=\"274\" y=\"150\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Loads ELF: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">New binary into RAM</tspan> </text> <text x=\"274\" y=\"171\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Preserves: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">PID, open FDs remain</tspan> </text> <text x=\"274\" y=\"192\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Start: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Begins at _start/main()</tspan> </text> </g> <g> <path d=\"M 440 195 L 490 195\" stroke=\"#06b6d4\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#mCyan)\"/> <g transform=\"translate(428.0, 185.0)\"> <rect width=\"74.0\" height=\"20\" rx=\"5\" fill=\"#0f172a\" stroke=\"#06b6d4\" stroke-width=\"1.2\" style=\"filter: drop-shadow(0 2px 5px rgba(0,0,0,0.5));\"/> <text x=\"37.0\" y=\"14\" fill=\"#f1f5f9\" font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\" font-family=\"system-ui, -apple-system, sans-serif\">exit(code)</text> </g> </g> <g> <rect x=\"490\" y=\"75\" width=\"180\" height=\"240\" rx=\"10\" fill=\"#0f172a\" stroke=\"#f43f5e\" stroke-width=\"1.5\" style=\"filter: drop-shadow(0 4px 12px rgba(0,0,0,0.4));\"/> <rect x=\"490\" y=\"75\" width=\"180\" height=\"32\" rx=\"10 10 0 0\" fill=\"#881337\"/> <text x=\"504\" y=\"96\" fill=\"#c7d2fe\" font-size=\"12\" font-weight=\"700\" font-family=\"system-ui, -apple-system, sans-serif\">3. Zombie State</text> <line x1=\"490\" y1=\"107\" x2=\"670\" y2=\"107\" stroke=\"#f43f5e\" stroke-width=\"1\" stroke-opacity=\"0.4\"/> <text x=\"504\" y=\"129\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Memory: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">RAM released immediately</tspan> </text> <text x=\"504\" y=\"150\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">PCB Entry: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Remains in process table</tspan> </text> <text x=\"504\" y=\"171\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Holds: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Exit status code for parent</tspan> </text> <text x=\"504\" y=\"192\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Danger: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Exhausts process table IDs</tspan> </text> </g> <g> <path d=\"M 670 195 L 720 195\" stroke=\"#10b981\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#mEmerald)\"/> <g transform=\"translate(649.0, 185.0)\"> <rect width=\"92.0\" height=\"20\" rx=\"5\" fill=\"#0f172a\" stroke=\"#10b981\" stroke-width=\"1.2\" style=\"filter: drop-shadow(0 2px 5px rgba(0,0,0,0.5));\"/> <text x=\"46.0\" y=\"14\" fill=\"#f1f5f9\" font-size=\"9.5\" font-weight=\"700\" text-anchor=\"middle\" font-family=\"system-ui, -apple-system, sans-serif\">wait(&status)</text> </g> </g> <g> <rect x=\"720\" y=\"75\" width=\"160\" height=\"240\" rx=\"10\" fill=\"#0f172a\" stroke=\"#10b981\" stroke-width=\"1.5\" style=\"filter: drop-shadow(0 4px 12px rgba(0,0,0,0.4));\"/> <rect x=\"720\" y=\"75\" width=\"160\" height=\"32\" rx=\"10 10 0 0\" fill=\"#064e3b\"/> <text x=\"734\" y=\"96\" fill=\"#c7d2fe\" font-size=\"12\" font-weight=\"700\" font-family=\"system-ui, -apple-system, sans-serif\">4. wait() Reaping</text> <line x1=\"720\" y1=\"107\" x2=\"880\" y2=\"107\" stroke=\"#10b981\" stroke-width=\"1\" stroke-opacity=\"0.4\"/> <text x=\"734\" y=\"129\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">wait(): </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Reads child exit status</tspan> </text> <text x=\"734\" y=\"150\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Reaped: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">PCB deleted from table</tspan> </text> <text x=\"734\" y=\"171\" font-family=\"system-ui, -apple-system, sans-serif\"> <tspan fill=\"#818cf8\" font-family=\"ui-monospace, SFMono-Regular, Menlo, monospace\" font-size=\"10.5\" font-weight=\"700\">Orphan: </tspan> <tspan fill=\"#e2e8f0\" font-size=\"11\">Adopted by PID 1 (init)</tspan> </text> </g> <g transform=\"translate(40, 335)\"> <rect width=\"840\" height=\"55\" rx=\"8\" fill=\"#0d1424\" stroke=\"#334155\" stroke-width=\"1.5\" style=\"filter: drop-shadow(0 2px 6px rgba(0,0,0,0.3));\"/> <text x=\"18\" y=\"21\" fill=\"#f8fafc\" font-size=\"11.5\" font-weight=\"700\" font-family=\"system-ui, sans-serif\">💡 UNIX Process Lifecycle Axiom: fork() -> exec() -> exit() -> wait()</text> <text x=\"18\" y=\"39\" fill=\"#94a3b8\" font-size=\"10.5\" font-family=\"system-ui, sans-serif\">If a parent dies without calling wait(), the child becomes an Orphan and is automatically adopted and reaped by PID 1 (systemd/init).</text> </g> </g> </svg>"}
